<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
$user=require_login(); if($user['role']==='system_admin'){header('Location: admin.php');exit;}
if($user['account_status']!=='approved'){http_response_code(403);exit('Account approval required.');}
$id=(int)($_GET['id']??0);$item=null;
if($id){$s=$pdo->prepare("SELECT * FROM content WHERE id=? AND owner_id=?");$s->execute([$id,$user['id']]);$item=$s->fetch();if(!$item){http_response_code(404);exit('Content not found.');}}
$categories=$pdo->query("SELECT id,name FROM categories WHERE is_active=1 ORDER BY name")->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim((string)($_POST['title']??''));$excerpt=trim((string)($_POST['excerpt']??''));$body=trim((string)($_POST['body']??''));$categoryId=(int)($_POST['category_id']??0);$type=(string)($_POST['content_type']??'article');$price=trim((string)($_POST['price']??''));$location=trim((string)($_POST['location']??''));$action=(string)($_POST['action']??'draft');
 if($title===''||$categoryId<1||!in_array($type,['article','product','property','video','news'],true))$error='Title, category and a valid content type are required.';
 else {
  $slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower($title)),'-').'-'.bin2hex(random_bytes(3));$status=$action==='submit'?'pending_review':'draft';$priceValue=$price===''?null:(float)$price;
  if($id){$s=$pdo->prepare("UPDATE content SET category_id=?,content_type=?,title=?,slug=?,excerpt=?,body=?,price=?,location=?,status=? WHERE id=? AND owner_id=?");$s->execute([$categoryId,$type,$title,$slug,$excerpt,$body,$priceValue,$location,$status,$id,$user['id']]);}
  else{$s=$pdo->prepare("INSERT INTO content(owner_id,category_id,content_type,title,slug,excerpt,body,price,location,status) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$user['id'],$categoryId,$type,$title,$slug,$excerpt,$body,$priceValue,$location,$status]);}
  header('Location: workspace.php');exit;
 }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit content</title><link rel="stylesheet" href="assets/css/site.css"></head><body><header><div class="wrap nav"><a class="brand" href="index.php">commonplace<span>.</span></a><a href="workspace.php">← Workspace</a></div></header><main class="wrap" style="max-width:900px;padding:38px 0"><div class="panel"><div class="eyebrow">Creator studio</div><h1 style="font:40px Georgia,serif"><?= $item?'Edit your content':'Create something new' ?></h1><p class="muted">Save a private draft or submit it for administrator review. Published content is visible on the public homepage.</p><?php if($error):?><p style="color:#a33"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="full"><label>Title *</label><input class="field" name="title" required maxlength="220" value="<?=e($item['title']??'')?>"></div><div><label>Category *</label><select class="field" name="category_id" required><?php foreach($categories as $cat):?><option value="<?=(int)$cat['id']?>" <?=isset($item['category_id'])&&(int)$item['category_id']===(int)$cat['id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></div><div><label>Content type</label><select class="field" name="content_type"><?php foreach(['article','product','property','video','news'] as $type):?><option value="<?=$type?>" <?=($item['content_type']??'article')===$type?'selected':''?>><?=ucfirst($type)?></option><?php endforeach;?></select></div><div class="full"><label>Short description</label><input class="field" name="excerpt" maxlength="500" value="<?=e($item['excerpt']??'')?>"></div><div class="full"><label>Body / details</label><textarea class="field" name="body" rows="9"><?=e($item['body']??'')?></textarea></div><div><label>Price (optional, PHP)</label><input class="field" name="price" type="number" min="0" step=".01" value="<?=e(isset($item['price'])?(string)$item['price']:'')?>"></div><div><label>Location (optional)</label><input class="field" name="location" value="<?=e($item['location']??'')?>"></div></div><p style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn light" name="action" value="draft">Save draft</button><button class="btn" name="action" value="submit">Submit for review</button></p></form></div></main></body></html>
